param([ValidateSet('Snapshot','Plan','Execute','Verify')][string]$Mode='Plan',[string]$Manifest)
$ErrorActionPreference='Stop';$connection=$null;$transaction=$null
try {
 $root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../../..'));$evidence=Join-Path $root 'tests/functional/artifacts/v2-integration';$baselinePath=Join-Path $evidence 'database-baseline.json'
 $connection=New-Object Data.SqlClient.SqlConnection('Server=localhost;Database=LeagueScramblerDev;Integrated Security=True;Application Name=V2OwnedFixtureCleanup;Connect Timeout=10;');$connection.Open()
 function Q([string]$sql,[hashtable]$parameters=@{}){
  $cmd=$connection.CreateCommand();$cmd.CommandTimeout=60;$cmd.CommandText=$sql;if($transaction){$cmd.Transaction=$transaction};foreach($key in $parameters.Keys){[void]$cmd.Parameters.AddWithValue($key,$parameters[$key])};$reader=$cmd.ExecuteReader();$rows=[Collections.Generic.List[object]]::new();try{while($reader.Read()){$row=[ordered]@{};for($i=0;$i -lt $reader.FieldCount;$i++){$value=$reader.GetValue($i);if($value -is [DBNull]){$value=$null};$row[$reader.GetName($i)]=$value};$rows.Add([pscustomobject]$row)}}finally{$reader.Dispose();$cmd.Dispose()};return ,$rows.ToArray()
 }
 $identity=Q "SELECT DB_NAME() AS db,CONVERT(nvarchar(128),SERVERPROPERTY('MachineName')) AS machine;";if($identity[0].db -cne 'LeagueScramblerDev' -or $identity[0].machine -ine $env:COMPUTERNAME){throw 'Wrong SQL identity'}
 function Quote([string]$name){return '['+$name.Replace(']',']]')+']'}
 function Snapshot {
  $tables=Q "SELECT s.name AS schemaName,t.name AS tableName FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE t.is_ms_shipped=0 ORDER BY s.name,t.name;";$result=@()
  foreach($table in $tables){$qualified=(Quote $table.schemaName)+'.'+(Quote $table.tableName);$pk=Q 'SELECT c.name FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE i.is_primary_key=1 AND i.object_id=OBJECT_ID(@table) ORDER BY ic.key_ordinal;' @{'@table'=$qualified};if(!$pk.Count){throw 'Cannot deterministically snapshot a table without primary key'};$order=($pk|ForEach-Object{Quote $_.name}) -join ',';$row=Q ("SELECT COUNT_BIG(*) AS [rowCount],CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT * FROM "+$qualified+' ORDER BY '+$order+" FOR JSON PATH,INCLUDE_NULL_VALUES))),2) AS signature FROM "+$qualified+';');$result+=[pscustomobject]@{table=$qualified;rows=[long]$row[0].rowCount;sha256=$row[0].signature}}
  return ,$result
 }
 if($Mode -eq 'Snapshot'){
  if(Test-Path -LiteralPath $baselinePath){throw 'A baseline already exists; preserve it instead of overwriting'};$snap=Snapshot;[pscustomobject]@{database='LeagueScramblerDev';createdUtc=[DateTime]::UtcNow.ToString('o');tables=$snap}|ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $baselinePath -Encoding UTF8;[pscustomobject]@{snapshotCreated=$true;tables=$snap.Count;database='LeagueScramblerDev'}|ConvertTo-Json -Compress;exit 0
 }
 if($Mode -eq 'Verify'){$baseline=Get-Content -LiteralPath $baselinePath -Raw|ConvertFrom-Json;$after=Snapshot;if(($baseline.tables|ConvertTo-Json -Depth 5 -Compress) -cne ($after|ConvertTo-Json -Depth 5 -Compress)){throw 'Post-commit database row signatures differ from baseline'};[pscustomobject]@{database='LeagueScramblerDev';postCommitBaselineMatches=$true;tablesVerified=$after.Count;verifiedUtc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress;exit 0}
 $manifestRoot=Join-Path $root 'tests/functional/artifacts/manifests';$fullManifest=[IO.Path]::GetFullPath($Manifest);if((Split-Path -Parent $fullManifest) -ine $manifestRoot -or (Split-Path -Leaf $fullManifest) -notmatch '^([a-f0-9]{24})\.json$'){throw 'Only exact harness manifest paths are accepted'};$runId=$Matches[1];$m=Get-Content -LiteralPath $fullManifest -Raw|ConvertFrom-Json
 if($m.runId -cne $runId -or $m.database -cne 'LeagueScramblerDev' -or $m.baseURL -cne 'https://localhost:5001' -or $m.test -cne 'Scrambler V2 persists a strict 40-player scramble with Top overflow through existing endpoints' -or @($m.leagues).Count -ne 1){throw 'Manifest scope mismatch'}
 $leagueEntry=$m.leagues[0];$expectedName='LSAuto_'+$runId+'_Lv2persistence';if($leagueEntry.name -cne $expectedName){throw 'Unexpected owned league name'}
 $authority=Get-Content -LiteralPath (Join-Path $root 'tests/functional/.local/manual-process-approval.json') -Raw|ConvertFrom-Json
 if($Mode -eq 'Execute'){
  if($authority.destructiveCleanupApproved -ne $true -or $authority.authorizedScopes -notcontains 'v2-owned-cleanup' -or $authority.cleanupScope.exactManifestIdsOnly -ne $true -or $authority.cleanupScope.testTitle -cne $m.test -or [DateTime]::Parse($authority.expiresAt).ToUniversalTime() -le [DateTime]::UtcNow){throw 'Exact owned-cleanup authorization is absent or expired'}
  $current=(& (Join-Path $root 'tests/functional/helpers/process-identity.ps1') |ConvertFrom-Json);foreach($field in 'pid','processStartUtc','projectDll','dllSha256','envSha256','launchProfileSha256'){if(!$current.$field -or $current.$field -cne $authority.identity.$field){throw 'Runtime binding changed'}}
 }
 $transaction=$connection.BeginTransaction([Data.IsolationLevel]::Serializable)
 $league=Q 'SELECT ID,LeagueName FROM dbo.LeagueType WITH(UPDLOCK,HOLDLOCK) WHERE LeagueName=@name;' @{'@name'=$expectedName};if($league.Count -ne 1 -or @($leagueEntry.snapshot.league).Count -ne 1 -or $league[0].ID -ne $leagueEntry.snapshot.league[0].ID){throw 'Exact owned league ID not verified'};$leagueId=[int]$league[0].ID
 $owned=@{};$keys=@{LeagueType='ID';User='UserId';Player='Id';UserLeague='UserLeagueId';LeagueSettings='LeagueSettingsId';PlayersLeague='ID';KingQueenTeam='Id';KingQueenPlayer='Id';KingQueenRoundScores='Id';ByeRounds='Id';ByePlayer='Id'}
 $owned['LeagueType']=@($leagueId);$owned['Player']=@($m.identities|ForEach-Object{$_.playerIds}|ForEach-Object{[int]$_});$owned['User']=@($m.identities|ForEach-Object{$_.userIds}|ForEach-Object{[int]$_})
 if($owned['Player'].Count -gt 41 -or $owned['User'].Count -gt 1 -or ($owned['Player']|Select-Object -Unique).Count -ne $owned['Player'].Count){throw 'Unexpected fixture identity counts'}
 foreach($entry in $m.identities){if($entry.firstName -cne ('LSAuto_'+$runId) -or $entry.lastName -notmatch '^Test_v2(?:admin|p\d+)$' -or $entry.email -notmatch ('^lsauto_'+$runId+'_[a-z0-9]+@example\.invalid$')){throw 'Unexpected fixture identity'};foreach($id in @($entry.playerIds)){$row=Q 'SELECT Id FROM dbo.Player WITH(UPDLOCK,HOLDLOCK) WHERE Id=@id AND FirstName=@first AND LastName=@last;' @{'@id'=[int]$id;'@first'=$entry.firstName;'@last'=$entry.lastName};if($row.Count -ne 1){throw 'Player ownership mismatch'}};foreach($id in @($entry.userIds)){$row=Q 'SELECT UserId FROM dbo.[User] WITH(UPDLOCK,HOLDLOCK) WHERE UserId=@id AND Email=@email AND FirstName=@first AND LastName=@last AND UserRoleId=1;' @{'@id'=[int]$id;'@email'=$entry.email;'@first'=$entry.firstName;'@last'=$entry.lastName};if($row.Count -ne 1){throw 'Account ownership mismatch'}}}
 $bindings=@{UserLeague=@('owners','LeagueTypeId');LeagueSettings=@('settings','LeagueId');PlayersLeague=@('memberships','LeagueID');KingQueenTeam=@('kqTeams','LeagueID');ByeRounds=@('byes','LeagueID')}
 foreach($table in $bindings.Keys){$key=$keys[$table];$snapshotField=$bindings[$table][0];$column=$bindings[$table][1];$actual=Q ('SELECT '+(Quote $key)+' AS Id FROM dbo.'+(Quote $table)+' WITH(UPDLOCK,HOLDLOCK) WHERE '+(Quote $column)+'=@id ORDER BY '+(Quote $key)) @{'@id'=$leagueId};$ids=@($actual|ForEach-Object{[int]$_.Id});$expected=@($leagueEntry.snapshot.$snapshotField|ForEach-Object{[int]$_.$key}|Sort-Object);if(($ids -join ',') -cne ($expected -join ',')){throw ('Manifest row IDs changed: '+$table)};$owned[$table]=$ids}
 foreach($binding in @(@('KingQueenPlayer','kqPlayers'),@('KingQueenRoundScores','kqScores'))){$table=$binding[0];$field=$binding[1];$actual=Q ('SELECT child.Id FROM dbo.'+(Quote $table)+' child WITH(UPDLOCK,HOLDLOCK) JOIN dbo.KingQueenTeam team ON team.Id=child.KingQueenTeamId WHERE team.LeagueID=@id ORDER BY child.Id') @{'@id'=$leagueId};$ids=@($actual|ForEach-Object{[int]$_.Id});$expected=@($leagueEntry.snapshot.$field|ForEach-Object{[int]$_.Id}|Sort-Object);if(($ids -join ',') -cne ($expected -join ',')){throw ('Manifest row IDs changed: '+$table)};$owned[$table]=$ids}
 $byes=Q 'SELECT bp.Id,bp.PlayerId FROM dbo.ByePlayer bp WITH(UPDLOCK,HOLDLOCK) JOIN dbo.ByeRounds br ON br.Id=bp.ByeRoundId WHERE br.LeagueID=@id ORDER BY bp.Id;' @{'@id'=$leagueId};foreach($bye in $byes){if($owned['Player'] -notcontains [int]$bye.PlayerId){throw 'Bye references a shared player'}};$owned['ByePlayer']=@($byes|ForEach-Object{[int]$_.Id})
 foreach($table in @($owned.Keys)){foreach($id in $owned[$table]){if($id -le 0){throw 'Invalid owned row ID'}};$trigger=Q 'SELECT tr.name FROM sys.triggers tr WHERE tr.parent_id=OBJECT_ID(@table) AND tr.is_disabled=0;' @{'@table'=('dbo.'+$table)};if($trigger.Count){throw 'Enabled trigger prevents isolated cleanup'}}
 # Check every incoming FK, including cascading relationships: no unowned referencing row may be deleted.
 $fks=Q 'SELECT f.object_id AS fkId,OBJECT_SCHEMA_NAME(f.parent_object_id) AS childSchema,OBJECT_NAME(f.parent_object_id) AS childTable,COL_NAME(fc.parent_object_id,fc.parent_column_id) AS childColumn,OBJECT_SCHEMA_NAME(f.referenced_object_id) AS parentSchema,OBJECT_NAME(f.referenced_object_id) AS parentTable,COL_NAME(fc.referenced_object_id,fc.referenced_column_id) AS parentColumn FROM sys.foreign_keys f JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id;'
 foreach($fk in $fks){if($fk.parentSchema -ne 'dbo' -or !$owned.ContainsKey($fk.parentTable) -or !$owned[$fk.parentTable].Count){continue};if(@($fks|Where-Object fkId -eq $fk.fkId).Count -ne 1){throw 'Composite FK requires separate review'};$parentIds=$owned[$fk.parentTable] -join ',';$childTable=(Quote $fk.childSchema)+'.'+(Quote $fk.childTable);$sql='SELECT COUNT_BIG(*) AS n FROM '+$childTable+' c JOIN dbo.'+(Quote $fk.parentTable)+' p ON c.'+(Quote $fk.childColumn)+'=p.'+(Quote $fk.parentColumn)+' WHERE p.'+(Quote $keys[$fk.parentTable])+' IN('+ $parentIds+')';if($fk.childSchema -eq 'dbo' -and $owned.ContainsKey($fk.childTable) -and $owned[$fk.childTable].Count){$sql+=' AND c.'+(Quote $keys[$fk.childTable])+' NOT IN('+($owned[$fk.childTable] -join ',')+')'};$outside=Q $sql;if([long]$outside[0].n -ne 0){throw ('External references prevent cleanup: '+$fk.childTable)}}
 $counts=[ordered]@{};foreach($table in ($owned.Keys|Sort-Object)){$counts[$table]=$owned[$table].Count};$plan=[pscustomobject]@{runId=$runId;leagueId=$leagueId;leagueName=$expectedName;ownedIds=$owned;counts=$counts;ownershipVerified=$true;outsideReferences=0;database='LeagueScramblerDev'}
 $plan|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $evidence ('cleanup-plan-'+$runId+'.json')) -Encoding UTF8
 if($Mode -eq 'Plan'){$transaction.Rollback();$transaction.Dispose();$transaction=$null;$plan|ConvertTo-Json -Depth 6 -Compress;exit 0}
 $baseline=Get-Content -LiteralPath $baselinePath -Raw|ConvertFrom-Json;if($baseline.database -cne 'LeagueScramblerDev'){throw 'Baseline scope mismatch'}
 foreach($table in @('KingQueenRoundScores','KingQueenPlayer','ByePlayer','ByeRounds','KingQueenTeam','PlayersLeague','LeagueSettings','UserLeague','LeagueType','Player','User')){if(!$owned[$table].Count){continue};$command=$connection.CreateCommand();$command.Transaction=$transaction;$command.CommandText='DELETE FROM dbo.'+(Quote $table)+' WHERE '+(Quote $keys[$table])+' IN('+($owned[$table] -join ',')+');';$removed=$command.ExecuteNonQuery();$command.Dispose();if($removed -ne $owned[$table].Count){throw 'Delete row count mismatch'}}
 $after=Snapshot;$beforeJson=($baseline.tables|ConvertTo-Json -Depth 5 -Compress);$afterJson=($after|ConvertTo-Json -Depth 5 -Compress);if($beforeJson -cne $afterJson){throw 'Database row signatures differ from pre-test baseline; rolling cleanup back'}
 # Process must still match its explicitly authorized identity at transaction completion.
 $current=(& (Join-Path $root 'tests/functional/helpers/process-identity.ps1')|ConvertFrom-Json);foreach($field in 'pid','processStartUtc','projectDll','dllSha256','envSha256','launchProfileSha256'){if($current.$field -cne $authority.identity.$field){throw 'Runtime changed during cleanup'}}
 $transaction.Commit();$transaction.Dispose();$transaction=$null;[pscustomobject]@{removed=$counts;runId=$runId;leagueId=$leagueId;database='LeagueScramblerDev';allTablesMatchPreTestBaseline=$true;tablesVerified=$after.Count;cleanupCommitted=$true}|ConvertTo-Json -Depth 5 -Compress
}catch{if($transaction){$transaction.Rollback()};[Console]::Error.WriteLine('Owned cleanup refused or rolled back: '+$_.Exception.Message);exit 1}finally{if($transaction){$transaction.Dispose()};if($connection){$connection.Dispose()}}
